    // § Icons: the SVG icon set and the emoji → icon converter
    // The icons are <symbol>s in the sprite at the top of <body> (#ic-…,
    // tier badges #tier-…). One line style drawn in currentColor; only the
    // Diamond, Gauntlet lives and rank tier badges are full colour (the tier
    // badges use the same metals as the crown pictures). icon('gift') /
    // tierBadge('Gold') give the markup. So that no UI shows an emoji icon,
    // every text node the game draws is passed through iconizeTextNode: the
    // UI emoji in EMOJI_ICON become icons. Emotes, effect art and seasonal
    // marks (EMOJI_KEEP) are left alone, since the emoji there are content.
    function icon(name, cls = '') {
      return `<svg class="ic ic-${name}${cls ? ` ${cls}` : ''}" aria-hidden="true" focusable="false"><use href="#ic-${name}"/></svg>`;
    }
    const RANK_TIER_IDS = ['novice', 'bronze', 'silver', 'gold', 'platinum', 'master'];
    function tierBadge(tier, cls = '') {
      const k = String(tier || 'novice').toLowerCase();
      return `<svg class="ic ic-tier${cls ? ` ${cls}` : ''}" aria-hidden="true" focusable="false"><use href="#tier-${RANK_TIER_IDS.includes(k) ? k : 'novice'}"/></svg>`;
    }
    const EMOJI_ICON = {
      '💎': 'gem', '🎁': 'gift', '🏆': 'trophy', '🔥': 'flame', '⚠': 'warning', '⚔': 'swords', '🗡': 'swords',
      '🎉': 'party', '🥳': 'party', '✨': 'sparkle', '🤖': 'bot', '🔗': 'link', '🔄': 'refresh', '🔃': 'refresh',
      '⏱': 'clock', '⏳': 'clock', '🔒': 'lock', '⭐': 'star', '🗑': 'trash', '✏': 'pencil', '✎': 'pencil',
      '👀': 'eye', '🔔': 'bell', '👥': 'users', '🛒': 'cart', '🛍': 'cart', '✅': 'check', '✔': 'check',
      '💾': 'save', '📤': 'share', '💥': 'burst', '⚡': 'bolt', '🃏': 'joker', '👑': 'crown', '🏅': 'trophy',
      '🎖': 'trophy', '🛡': 'shield', '🎮': 'cards', '📊': 'leader', '🥇': 'place1', '🥈': 'place2', '🥉': 'place3',
      '🧧': 'ev-lunar', '💘': 'ev-valentine', '🌙': 'ev-ramadan', '🐣': 'ev-easter', '☀': 'ev-summer', '🎃': 'ev-halloween',
      '🪔': 'ev-diwali', '🎄': 'ev-christmas', '🎆': 'ev-newyear', '💩': 'poo', '☝': 'lastcard', '📴': 'warning', '🎓': 'star',
      '🎨': 'sparkle', '🔑': 'lock', '📋': 'cards', '🏠': 'online', '📶': 'online', '🔕': 'bell', '🙈': 'eye', '🪵': 'cards',
      '🗂': 'cards', '🖐': 'cards', '🏷': 'gift', '📱': 'share', '🎴': 'cards', '📐': 'cards', '📳': 'bell', '🧨': 'burst',
      '🔽': 'refresh', '🎯': 'star', '💔': 'close', '🚫': 'close', '⚑': 'warning', '📖': 'cards', '🖼': 'sparkle', '🙋': 'users',
      '👋': 'users', '🤝': 'users', '📅': 'clock', '📥': 'share', '📜': 'cards', '🧪': 'sparkle', '👕': 'sparkle', '🎇': 'ev-newyear', '⬇': 'download', '👆': 'tap'
    };
    const EMOJI_ICON_RE = new RegExp(`(?:${Object.keys(EMOJI_ICON).join('|')})\uFE0F?`, 'gu');
    const EMOJI_KEEP = '#emoteLayer, [data-keep-emoji], .emote-float, .effect-mini-tile, .shop-burn-core, .jfx-stage, .jfx-stage-hint, .pp-show-icon, .bfx, #jokerFxLayer, #victoryFxLayer, #burnFxLayer, .shop-preview-stage, textarea, script, style';
    const iconTemplate = document.createElement('template');
    function iconizeTextNode(node) {
      const text = node.data;
      EMOJI_ICON_RE.lastIndex = 0;
      if (!text || !EMOJI_ICON_RE.test(text)) return;
      const parent = node.parentElement;
      if (!parent || parent.closest('svg') || parent.closest(EMOJI_KEEP)) return;
      const frag = document.createDocumentFragment();
      let last = 0, m;
      EMOJI_ICON_RE.lastIndex = 0;
      while ((m = EMOJI_ICON_RE.exec(text))) {
        if (m.index > last) frag.appendChild(document.createTextNode(text.slice(last, m.index)));
        iconTemplate.innerHTML = icon(EMOJI_ICON[m[0].replace(/\uFE0F/g, '')]);
        frag.appendChild(iconTemplate.content.firstChild);
        last = m.index + m[0].length;
      }
      if (last < text.length) frag.appendChild(document.createTextNode(text.slice(last)));
      node.replaceWith(frag);
    }
    function iconizeEmoji(root) {
      if (root.nodeType === 3) { iconizeTextNode(root); return; }
      if (root.nodeType !== 1 || root.closest?.('svg')) return;
      const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
      const found = [];
      for (let n = walker.nextNode(); n; n = walker.nextNode()) { EMOJI_ICON_RE.lastIndex = 0; if (EMOJI_ICON_RE.test(n.data)) found.push(n); }
      found.forEach(iconizeTextNode);
    }
    new MutationObserver((mutations) => {
      for (const m of mutations) {
        if (m.type === 'characterData') iconizeTextNode(m.target);
        else m.addedNodes.forEach(iconizeEmoji);
      }
    }).observe(document.body, { childList: true, subtree: true, characterData: true });
    iconizeEmoji(document.body);

    // § Start-up plumbing: pages to <body>, Firebase, error reports
    // Pages and pop-ups live at the top level of <body>. Written inside the
    // game table, any transform on the table (the burn screen-shake, some
    // browsers' compositing) made their position:fixed boxes start at the
    // table's top instead of the screen's, pushing the top and X of a tall
    // page (e.g. Profile on iPhone) under the header.
    ['houseNameModal', 'friendsConfigModal', 'matchStatsModal', 'historyGameModal', 'modeIntroModal', 'tutorialHubScreen', 'settingsModal', 'authModal', 'usernameModal', 'difficultyUnlockPopup',
     'friendsModal', 'inboxModal', 'leaderboardModal', 'profileModal', 'deleteAccountModal', 'supportModal',
     'shopModal', 'challengesModal', 'statsModal', 'themesModal', 'pileInspectModal', 'needHumanModal', 'rulesModal',
     'matchSummaryModal', 'errorReportsModal', 'changelogModal', 'rejoinModal', 'whatsNewModal', 'gauntletModal', 'referralWelcomeModal', 'keepAccountModal', 'collectionModal', 'levelLadderModal', 'seriesModal',
     // v281: #gameTable is isolation:isolate (v270 table scenes), so anything
     // left inside it can never sit above a page, whatever its z-index.
     'playerPopup', 'challengeToast', 'signOutConfirm', 'dailyRewardModal', 'giftModal', 'giftOpenModal', 'installHelpModal', 'shConfirm'].forEach((id) => {
      const el = document.getElementById(id);
      if (el && el.parentElement !== document.body) document.body.appendChild(el);
    });
    // v284 (owner): every menu page shows its menu icon beside its title,
    // the way Shop and Custom already did.
    const PAGE_TITLE_ICONS = {
      profileModal: 'ui-profile', statsModal: 'ui-stats', friendsModal: 'ui-friends', leaderboardModal: 'ui-leaderboard',
      challengesModal: 'ui-challenges', levelLadderModal: 'ui-ladder', rulesModal: 'ui-guide', settingsModal: 'ui-settings',
      supportModal: 'ui-support', inboxModal: 'ui-mail'
    };
    Object.entries(PAGE_TITLE_ICONS).forEach(([id, icon]) => {
      const page = document.getElementById(id);
      const title = !page ? null
        : id === 'rulesModal' ? page.querySelector('h3')
        : id === 'levelLadderModal' ? page.querySelector('.ll-title > span')
        : page.querySelector('span.text-amber-400.tracking-widest');
      if (!title || title.querySelector('.page-title-icon')) return;
      title.querySelectorAll(':scope > svg').forEach(svg => svg.remove());
      title.classList.add('page-title-has-icon');
      title.insertAdjacentHTML('afterbegin', `<svg class="pack-icon page-title-icon" viewBox="0 0 32 32" aria-hidden="true"><use href="#${icon}"/></svg>`);
    });
    // Google sign-in runs its redirect handler (/__/auth/handler) on the
    // SAME domain the game is served from. With the default firebaseapp.com
    // handler on a web.app page, phones that partition storage per site
