    function weeklyRulesFor(weekKey) {
      const key = String(weekKey || '');
      let rule = WEEKLY_CHALLENGE_RULES[0];
      WEEKLY_CHALLENGE_RULES.forEach((r) => { if (key >= r.from) rule = r; });
      return rule;
    }
