    window.addEventListener('resize', () => positionMatrixRefPanel());

    // Guards a button so it only fires on a genuine tap — a press that
    // STARTS on this element and is released without significant movement.
    // Without this, a touch that merely drifts across the screen and happens
    // to LIFT over a small, frequently-repositioned button still fires a
    // normal click in most mobile browsers, even though the person never
    // intended to press it. That's an easy accident on the tutorial's
    // Continue/Back/Skip buttons specifically, since they sit in the exact
    // same screen position on every step — a stray touch (adjusting grip on
    // the phone, a swipe that drifts) can "activate" whichever one is
    // sitting there, which looks indistinguishable from the tutorial
    // silently advancing on its own.
    function bindTapOnly(el, handler) {
      if (!el) return;
      const THRESHOLD = 12; // px of allowed movement to still count as a tap
      let startX = null, startY = null, trackingPointer = false;
      el.addEventListener('pointerdown', (e) => {
        startX = e.clientX; startY = e.clientY; trackingPointer = true;
      });
      el.addEventListener('click', (e) => {
        if (!trackingPointer) { handler(e); return; } // keyboard/synthetic activation — no drag to check
        trackingPointer = false;
        const dx = e.clientX - startX, dy = e.clientY - startY;
        if (Math.hypot(dx, dy) > THRESHOLD) return; // drag-release, not a real tap — ignore
        handler(e);
      });
    }

